@module voicing  src=voicing.lua  loc=70  mode=namespace  self=voicing

# Imports
  @const util = 'util'  @ 5
      @invariant  pure policy module: no module state; callers stage every mm write  @ 4

# Module-level constants
  @const voicing = {}  @ 7

# Private functions
  -- Verdicts
  @fn supersedes(a, b)  @ 13-17
      -- Dedup same-(chan,pitch) raw collision only when one is a regenerable fxNote or they share
      -- logical seat and detune; otherwise distinct voices: separate (+1) so each keeps its raw.
  @fn redundant(a, b)  @ 19-22

# Public API (voicing.*)
  -- Separation
  @api voicing.resolveGroup(group)  @ 27-33
      @contract  sorts group (ppq, ppqL) in place, then delegates to resolveSorted  @ 26
  @api voicing.resolveSorted(group)  @ 38-61
      -- The sorted door, for a caller whose group arrives already ordered (tm's flush scan
      -- buckets the raw index, which is sorted already). see docs/voicing.md
      @contract  caller guarantees (ppq, ppqL) order; returns kills, voiced, onsetOf (separated onsets)  @ 37
  @api voicing.separateOnset(e, prev)  @ 66-68
      -- The separation verdict for one collision: give way by a tick, unless the note is a fixed
      -- external. Callers own the traversal (whose order decides the cascade) and stage mm writes.
      @contract  e's separated raw onset given its settled same-(chan,pitch) predecessor; nil if e stands  @ 65

# Uses (outbound edges)
  @use call    util.add  @ resolveSorted:47,49,53,57
  @use require util  @ 5

# Calls (intra-file)
  @call voicing.resolveSorted  @ resolveGroup:32

# Fields (r read / w write incl. constructor keys)
  @field r derived  @ supersedes:14 redundant:20
  @field r detune  @ redundant:21
  @field r endppq  @ supersedes:16
  @field r endppqL  @ supersedes:16
  @field r fixed  @ separateOnset:67
  @field r ppq  @ resolveGroup:29 resolveSorted:44,56 separateOnset:67
  @field r ppqL  @ redundant:21 resolveGroup:30
  @field w resolveGroup  @ resolveGroup:27
  @field w resolveSorted  @ resolveSorted:38
  @field w separateOnset  @ separateOnset:66
